/**
 * Contracts for the committed home-page snapshot. The snapshot is generated by
 * `scripts/home/build-home-snapshot.ts` and is the only data source for first
 * paint of `/`. It never contains user-specific state.
 */

/**
 * Home themes. Collaboration is the default and has no hash. `#nexafs` and
 * `#spectra` select Data. `#molecules` selects the catalog. `#fair` selects
 * collaboration.
 */
export type HomePillarId =
  | "hierarchies"
  | "nexafs"
  | "provenance"
  | "collaboration";

/**
 * Theme shown in the home hero. Every theme is a {@link HomePillarId}.
 * Collaboration is the empty-hash default.
 */
export type HomeStageId = HomePillarId;

/** Spectrum feature tabs; absent data drops the tab at generation time. */
export type HomeSpectrumTabId =
  | "absorption"
  | "polarization"
  | "normalization"
  | "optical"
  | "processing"
  | "compare";

export interface HomeSnapshotLink {
  /** Experiment UUID. */
  experimentId: string;
  /** Edge label, e.g. "C K". */
  edge: string;
  /** Detection token: TEY | PEY | FY | TRANS. */
  detection: string;
  instrument: string;
  facility: string;
}

export interface HomeSnapshotMolecule {
  id: string;
  slug: string;
  name: string;
  formula: string;
  imageUrl: string | null;
  /** One sentence, hand-authored in the generator's curation table. */
  blurb: string;
  datasetCount: number;
  favoriteCount: number;
  /** Up to 4 experiments used for the linking graph. */
  links: readonly HomeSnapshotLink[];
}

export interface HomeSpectrumTrace {
  key: string;
  label: string;
  /** SVG path data in viewBox coordinates. */
  d: string;
  /** "primary" = accent stroke, "muted" = foreground/40, ramp = 0..1 position on polarization ramp. */
  tone: "primary" | "muted" | { ramp: number };
  dashed?: boolean;
}

export interface HomeSpectrumBand {
  x0: number;
  x1: number;
  kind: "pi" | "sigma" | "pre" | "post";
  label: string;
}

/**
 * A labeled sample on a home spectrum.
 *
 * `point` marks sit on the trace in the trace color. Other marks share one
 * row of leader callouts above the curves.
 */
export interface HomeSpectrumMarker {
  /** ViewBox x of the marked sample. */
  x: number;
  /** ViewBox y of the marked sample. */
  y: number;
  /** Text drawn for the mark. */
  label: string;
  /**
   * `point` draws a dot on the sample and the label beside it.
   * Omit for the shared row of leader callouts.
   */
  placement?: "row" | "point";
  /** Grey-to-red ramp in [0, 1] for a `point` mark. Omit for the default text color. */
  ramp?: number;
}

export interface HomeSpectrumTab {
  id: HomeSpectrumTabId;
  label: string;
  caption: string;
  wikiHref: string;
  yLabel: string;
  traces: readonly HomeSpectrumTrace[];
  bands: readonly HomeSpectrumBand[];
  markers: readonly HomeSpectrumMarker[];
  /** Horizontal reference lines (viewBox y) such as the 0 and 1 normalization levels. */
  refLines?: readonly HomeSpectrumRefLine[];
  /**
   * Numeric y ticks on the shared data domain of this tab. Absent on snapshots
   * generated before the chart-frame revision; the figure then draws the frame
   * without numeric y labels.
   */
  yTicks?: readonly HomeSpectrumYTick[];
}

export interface HomeSpectrumRefLine {
  y: number;
  label: string;
}

export interface HomeSpectrumTick {
  x: number;
  label: string;
}

/**
 * Y-axis tick in the same viewBox as the trace paths.
 *
 * A minor tick is an unlabeled subdivision, used between decades on a
 * logarithmic axis. Major ticks carry `label` and the grid line. When
 * `exponent` is set, the figure draws `label` with that power of ten as a
 * superscript instead of computer `e` notation.
 */
export interface HomeSpectrumYTick {
  /** ViewBox y of the tick. */
  y: number;
  /**
   * Data-unit label, already formatted. Empty for a minor tick. On a
   * logarithmic axis this is `10` for a decade or the mantissa `2`–`9`.
   */
  label: string;
  /** Unlabeled tick between major ticks. Omit for a labeled major tick. */
  minor?: boolean;
  /**
   * Power of ten drawn as a superscript on `label`. Omit for a linear tick.
   * A decade uses `label` `"10"`; any other mantissa is drawn as `m × 10`.
   */
  exponent?: number;
}

export interface HomeSnapshotSpectrum {
  moleculeSlug: string;
  experimentId: string;
  title: string;
  width: number;
  height: number;
  xTicks: readonly HomeSpectrumTick[];
  tabs: readonly HomeSpectrumTab[];
}

/** One carbon K-edge dataset in the home collaboration comparison. */
export interface HomeCollaborationDataset {
  experimentId: string;
  slug: string;
  name: string;
  formula: string;
  imageUrl: string | null;
  /**
   * Optical density on the shared energy grid from `energyMinEv` to
   * `energyMaxEv`, one sample per grid knot, same length for every dataset.
   */
  od: readonly number[];
  /** Imaginary refractive index `β` on the same grid as `od`. */
  beta: readonly number[];
  /**
   * Real refractive decrement `δ` on the same grid as `od`.
   * `n = 1 - δ + iβ`. Computed by the snapshot Kramers-Kronig transform of `β`
   * at 1 g/cm³ so the three molecules share one index convention.
   */
  delta: readonly number[];
  /**
   * `β` on the wider vacuum-contrast grid from `vacuumEnergyMinEv` to
   * `vacuumEnergyMaxEv`. Same length as `vacuumDelta`.
   */
  vacuumBeta: readonly number[];
  /** `δ` on the same wider grid as `vacuumBeta`. `n = 1 - δ + iβ`. */
  vacuumDelta: readonly number[];
}

/**
 * Opening comparison for the Collaboration feature.
 *
 * The near-edge grid is 283–289 eV. Vacuum contrast uses the wider grid from
 * `vacuumEnergyMinEv` to `vacuumEnergyMaxEv`. `spectrum` is the overlay of
 * every dataset on the near-edge window. `beta` and `delta` support the
 * binary contrast `|n_i - n_j|² / E⁴`. `vacuumBeta` and `vacuumDelta` support
 * the vacuum contrast `(δ² + β²) / E⁴`.
 */
export interface HomeCollaboration {
  /** First knot of the near-edge grid, in eV. */
  energyMinEv: number;
  /** Last knot of the near-edge grid, in eV. */
  energyMaxEv: number;
  /** First knot of the vacuum-contrast grid, in eV. */
  vacuumEnergyMinEv: number;
  /** Last knot of the vacuum-contrast grid, in eV. */
  vacuumEnergyMaxEv: number;
  /** Overlay chart for the full grid. Width and height are the viewBox. */
  spectrum: HomeSnapshotSpectrum;
  datasets: readonly [
    HomeCollaborationDataset,
    HomeCollaborationDataset,
    HomeCollaborationDataset,
  ];
}

export interface HomeEdgeOption {
  /** Element symbol, e.g. "C". */
  symbol: string;
  edgeId: string;
  /** e.g. "C K". */
  label: string;
}

export interface HomeSnapshot {
  generatedAt: string;
  /** Three molecules shown in the catalog. */
  molecules: readonly [
    HomeSnapshotMolecule,
    HomeSnapshotMolecule,
    HomeSnapshotMolecule,
  ];
  /**
   * Molecule that owns `spectrum`. Kept apart from `molecules` so the catalog
   * can feature a different trio than the measurement drawn on Data and
   * Provenance.
   */
  showcaseMolecule: HomeSnapshotMolecule;
  spectrum: HomeSnapshotSpectrum;
  /** Three carbon K-edge spectra at one angle, drawn on the Collaboration feature. */
  collaboration: HomeCollaboration;
  edges: readonly HomeEdgeOption[];
}
